class Solution:
    def countLocalMaximums(self, matrix: List[List[int]]) -> int:
        n = len(matrix)
        m = len(matrix[0])
        count = 0

        for r in range(n):
            for c in range(m):
                x = matrix[r][c]
                if x == 0:
                    continue

                is_local_max = True
                for dr in range(-x, x + 1):
                    for dc in range(-x, x + 1):
                        # Ignore cells where both row distance and column distance are exactly x
                        if abs(dr) == x and abs(dc) == x:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if matrix[nr][nc] > x:
                                is_local_max = False
                                break
                    if not is_local_max:
                        break

                if is_local_max:
                    count += 1

        return count

