class Solution:
    def largestString(self, nums: List[int]) -> List[str]:
        ans = []
        for x in nums:
            s = 'a' * x
            ans.append(self._transform(s))
        return ans

    def _transform(self, s: str) -> str:
        # Greedy left-to-right merging using a stack.
        # Each element in stack is an integer 0-25 representing 'a'-'z'.
        arr = [ord(c) - 97 for c in s]
        stack = []
        for val in arr:
            stack.append(val)
            # While the last two letters are equal and not 'z', merge them.
            while len(stack) >= 2 and stack[-1] == stack[-2] and stack[-1] < 25:
                v = stack.pop()      # pop the top
                stack.pop()          # pop the new top (which equals v)
                stack.append(v + 1)  # push the next letter
        return ''.join(chr(v + 97) for v in stack)

class Solution:
    def longestSubarray(self, nums: list[int], k: int) -> int:
        n = len(nums)
        # Prefix sums for O(1) subarray sum queries
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        best = 0
        # Check every subarray nums[i:j] (i inclusive, j exclusive)
        for i in range(n):
            for j in range(i + 1, n + 1):
                sub_sum = pref[j] - pref[i]
                # Condition 1: sum already divisible by k
                if sub_sum % k == 0:
                    best = max(best, j - i)
                    continue
                # Condition 2: negating one element x makes sum divisible
                # i.e., (sub_sum - 2*x) % k == 0  <=>  sub_sum % k == (2*x) % k
                target = sub_sum % k
                for idx in range(i, j):
                    x = nums[idx]
                    if (2 * x) % k == target:
                        best = max(best, j - i)
                        break

        return best

