import heapq

class Solution:
    def shortestPath(self, n: int, edges: list[list[int]], labels: str, k: int) -> int:
        # Build adjacency list
        adj = defaultdict(list)
        for u, v, w in edges:
            adj[u].append((v, w))

        # (distance, node, last_char, consecutive_count)
        # Start from node 0
        start_char = labels[0]
        pq = [(0, 0, start_char, 1)]
        best = {}
        best[(0, start_char, 1)] = 0

        while pq:
            dist, node, last_char, consec = heapq.heappop(pq)
            if best.get((node, last_char, consec), float('inf')) < dist:
                continue
            if node == n - 1:
                return dist

            for nxt, w in adj[node]:
                nxt_char = labels[nxt]
                if nxt_char == last_char:
                    new_consec = consec + 1
                else:
                    new_consec = 1
                if new_consec > k:
                    continue
                new_dist = dist + w
                state = (nxt, nxt_char, new_consec)
                if new_dist < best.get(state, float('inf')):
                    best[state] = new_dist
                    heapq.heappush(pq, (new_dist, nxt, nxt_char, new_consec))

        return -1

class Solution:
    def smallestUniqueSubarray(self, nums: list[int]) -> int:
        n = len(nums)
        # Build Suffix Automaton
        max_states = 2 * n
        length = [0] * max_states
        link = [-1] * max_states
        next_dict = [{} for _ in range(max_states)]
        cnt = [0] * max_states

        size = 1  # number of states, state 0 is root
        last = 0

        for c in nums:
            cur = size
            size += 1
            length[cur] = length[last] + 1
            cnt[cur] = 1  # this state corresponds to a prefix
            p = last
            while p != -1 and c not in next_dict[p]:
                next_dict[p][c] = cur
                p = link[p]
            if p == -1:
                link[cur] = 0
            else:
                q = next_dict[p][c]
                if length[p] + 1 == length[q]:
                    link[cur] = q
                else:
                    clone = size
                    size += 1
                    length[clone] = length[p] + 1
                    next_dict[clone] = next_dict[q].copy()
                    link[clone] = link[q]
                    while p != -1 and next_dict[p].get(c) == q:
                        next_dict[p][c] = clone
                        p = link[p]
                    link[q] = link[cur] = clone
            last = cur

        # Propagate cnt using counting sort by length
        max_len = n
        bucket = [[] for _ in range(max_len + 1)]
        for i in range(size):
            l = length[i]
            if l <= max_len:
                bucket[l].append(i)

        for l in range(max_len, -1, -1):
            for v in bucket[l]:
                if link[v] != -1:
                    cnt[link[v]] += cnt[v]

        ans = n  # worst case: whole array is unique
        for v in range(size):
            if cnt[v] == 1 and link[v] != -1:
                ans = min(ans, length[link[v]] + 1)
        return ans

