        count = 0
        for l in range(n):
            s = 0
            for r in range(l, n):
                s += nums[r]
                # Compute first and last digit of s
                last = abs(s) % 10
                temp = abs(s)
                while temp >= 10:
                    temp //= 10
                first = temp
